package com.bananalab.lite;
import java.util.*;import java.util.regex.*;
/** Small token policy: permits only bounded text conditions and returns, even during diagnosis. */
final class RepairSyntax{
 static final String[] RULES={"semicolon","method_name","string_equals","final_null","if_block"};
 static final Set<String> WORDS=new HashSet<>(Arrays.asList("if","text","message","equals","equal","Equals","startsWith","startswith","StartsWith","endsWith","endswith","EndsWith","contains","Contains","return","null"));
 static final class Token{String value;int start,end;boolean literal;Token(String v,int s,int e,boolean l){value=v;start=s;end=e;literal=l;}}
 static List<Token> tokens(String source)throws Exception{if(source.trim().isEmpty())throw new IllegalArgumentException("Escribí el cuerpo que querés diagnosticar.");if(source.length()>6000||source.contains("\\u"))throw new IllegalArgumentException("El reparador admite un cuerpo de hasta6000 caracteres y sin escapes Unicode.");List<Token> out=new ArrayList<>();Pattern lit=Pattern.compile(JavaTextPlan.LIT);int parens=0,braces=0;for(int i=0;i<source.length();){char c=source.charAt(i);if(Character.isWhitespace(c)){i++;continue;}int start=i;if(c=='\"'){Matcher m=lit.matcher(source);m.region(i,source.length());if(!m.lookingAt())throw new IllegalArgumentException("Hay una cadena sin cerrar o un escape desconocido. No voy a inventar el texto faltante.");String raw=m.group();if(JavaTextPlan.decode(raw).length()>400)throw new IllegalArgumentException("Texto demasiado largo.");i=m.end();out.add(new Token(raw,start,i,true));}else if(Character.isLetter(c)){i++;while(i<source.length()&&Character.isLetter(source.charAt(i)))i++;String word=source.substring(start,i);if(!WORDS.contains(word))throw new IllegalArgumentException("Fuera del reparador de texto: "+word);out.add(new Token(word,start,i,false));}else{if("().;={}!".indexOf(c)<0)throw new IllegalArgumentException("Símbolo fuera del reparador: "+c);if(c=='('&&++parens>32||c=='{'&&++braces>8)throw new IllegalArgumentException("Cuerpo demasiado anidado.");if(c==')')parens--;if(c=='}')braces--;i++;out.add(new Token(String.valueOf(c),start,i,false));}if(out.size()>240)throw new IllegalArgumentException("Hasta240 tokens por reparación.");}return out;}
 static String fix(String source,String rule)throws Exception{List<Token> tokens=tokens(source);if(rule.equals("semicolon")){StringBuilder next=new StringBuilder(source);for(int i=tokens.size()-2;i>=0;i--){Token t=tokens.get(i),value=tokens.get(i+1);if(t.value.equals("return")&&(value.literal||value.value.equals("null"))&&(i+2==tokens.size()||!tokens.get(i+2).value.equals(";")))next.insert(value.end,';');}return next.toString();}
  if(rule.equals("method_name")){StringBuilder next=new StringBuilder(source);Map<String,String> names=new HashMap<>();names.put("equal","equals");names.put("Equals","equals");names.put("startswith","startsWith");names.put("StartsWith","startsWith");names.put("endswith","endsWith");names.put("EndsWith","endsWith");names.put("Contains","contains");for(int i=tokens.size()-2;i>=1;i--){Token t=tokens.get(i);if(!t.literal&&names.containsKey(t.value)&&tokens.get(i-1).value.equals(".")&&tokens.get(i+1).value.equals("("))next.replace(t.start,t.end,names.get(t.value));}return next.toString();}
  if(rule.equals("string_equals")){StringBuilder next=new StringBuilder(source);for(int i=tokens.size()-4;i>=0;i--){Token a=tokens.get(i),b=tokens.get(i+1),c=tokens.get(i+2),value=tokens.get(i+3);if((a.value.equals("text")||a.value.equals("message"))&&b.value.equals("=")&&c.value.equals("=")&&value.literal)next.replace(a.start,value.end,a.value+".equals("+value.value+")");}return next.toString();}
  if(rule.equals("final_null")){if(tokens.size()>=3&&tokens.get(tokens.size()-3).value.equals("return")&&tokens.get(tokens.size()-2).value.equals("null")&&tokens.get(tokens.size()-1).value.equals(";"))return source;return source+"\nreturn null;";}
  if(rule.equals("if_block")){StringBuilder next=new StringBuilder(source);for(int i=tokens.size()-5;i>=0;i--){if(tokens.get(i).value.equals("{")&&tokens.get(i+1).value.equals("return")&&tokens.get(i+2).literal&&tokens.get(i+3).value.equals(";")&&tokens.get(i+4).value.equals("}")&&i>0&&tokens.get(i-1).value.equals(")")){next.deleteCharAt(tokens.get(i+4).start);next.deleteCharAt(tokens.get(i).start);}}return next.toString();}return source;
 }
 static String canonical(String body)throws Exception{return fix(fix(body,"string_equals"),"if_block");}
 static String compileSource(String base,String body)throws Exception{tokens(body);String source=new JavaTextPlan().compiled(base);int[] span=JavaTextPlan.span(source);return source.substring(0,span[0])+"\n String text=normalize(message).replaceFirst(\"^banana \",\"\");\n"+body+"\n"+source.substring(span[1]);}
 static JavaTextPlan reference(String body)throws Exception{JavaTextPlan p=JavaTextPlan.raw(canonical(body));p.controls();return p;}
 static String next(String body,Set<String> applied,String[] order)throws Exception{for(String rule:order){if(applied.contains(rule))continue;String changed=fix(body,rule);if(!changed.equals(body)){applied.add(rule);return changed;}}return body;}
}
